(2631842, 364070, 47852, '<td valign="top">Hmm.. a cracker?  I like this!  Abstract without being too awkward and strange, and the border is nice too, neat but unobtrusive.  Well done!</td>', 'Hmm.. a cracker?  I like this!  Abstract without being too awkward and strange, and the border is nice too, neat but unobtrusive.  Well done!', '2006-07-18 01:13:21.000000', NULL, 1),
(2631909, 364618, 50931, '<td valign="top">very nice. well composed and more abstracted than a lot of the entries i have seen so far. my only complaint is some banding artifacts in the midtones.</td>', 'very nice. well composed and more abstracted than a lot of the entries i have seen so far. my only complaint is some banding artifacts in the midtones.', '2006-07-18 01:41:07.000000', NULL, 1),
(2631917, 364411, 50931, '<td valign="top">a tighter crop (just the center pattern without the outline of the roll) would have made this more of an abstraction and gotten a higher vote from me. 5</td>', 'a tighter crop (just the center pattern without the outline of the roll) would have made this more of an abstraction and gotten a higher vote from me. 5', '2006-07-18 01:43:43.000000', NULL, 1),
