(2631924, 363998, 50931, '<td valign="top">the post processing is a little too much for me</td>', 'the post processing is a little too much for me', '2006-07-18 01:46:02.000000', NULL, 1),
(2631928, 364559, 50931, '<td valign="top">you know, this looked enough like coral that i was about to score it low (hey, that''s not food!). it took me a minute to realize what was really going on. that is good abstraction, which is more than i can say for a lot of other entries. good color and compsition to boot. 9</td>', 'you know, this looked enough like coral that i was about to score it low (hey, that''s not food!). it took me a minute to realize what was really going on. that is good abstraction, which is more than i can say for a lot of other entries. good color and compsition to boot. 9', '2006-07-18 01:49:34.000000', NULL, 1),
(2631929, 364899, 50578, '<td valign="top">almost looks like strawberry twizzlers.  Nice colors, looks abstract too.</td>', 'almost looks like strawberry twizzlers.  Nice colors, looks abstract too.', '2006-07-18 01:49:36.000000', NULL, 1),
