(2633707, 362043, 33068, '<td valign="top">Dude....the avocado is rotten.  You should have made guac before you let it get to that stage.  What a sin!  JK</td>', 'Dude....the avocado is rotten.  You should have made guac before you let it get to that stage.  What a sin!  JK', '2006-07-18 18:03:54.000000', NULL, 1),
(2633713, 362903, 61432, '<td valign="top">Hmm, looks like a cluster of eggs on the belly of a giant isopod. I like the total lack of foodlikenes. This is not what I imagine eating on a hot summers day (and I mean that in a good sense), which is all part of your well executed abstraction . Also I like the colors, again not at all like food.</td>', 'Hmm, looks like a cluster of eggs on the belly of a giant isopod. I like the total lack of foodlikenes. This is not what I imagine eating on a hot summers day (and I mean that in a good sense), which is all part of your well executed abstraction . Also I like the colors, again not at all like food.', '2006-07-18 18:05:00.000000', NULL, 1),
(2633716, 364889, 34192, '<td valign="top">no clue what it is but it looks cool.  Colors are excellent. 8</td>', 'no clue what it is but it looks cool.  Colors are excellent. 8', '2006-07-18 18:05:32.000000', NULL, 1),
(2633717, 362196, 17507, '<td valign="top">the duotone was a good idea. it highlights the shapes well and makes pleasing color fields out of the shadow area.</td>', 'the duotone was a good idea. it highlights the shapes well and makes pleasing color fields out of the shadow area.', '2006-07-18 18:05:44.000000', NULL, 1),
(2633718, 364912, 33068, '<td valign="top">Like the colors.</td>', 'Like the colors.', '2006-07-18 18:06:35.000000', NULL, 1),
