(2645824, 364861, 61234, '<td valign="top">Excellent work. What came first; the great title or the image? Love everything about it. Bet it will be a top ten!</td>', 'Excellent work. What came first; the great title or the image? Love everything about it. Bet it will be a top ten!', '2006-07-21 11:05:03.000000', NULL, 1),
(2645922, 364497, 44611, '<td valign="top">This is a superb abstract.  I just love the whole feel of it and the colours.  Can''t really tell that it is food at all.  Please let us know how you created this after voting is over.</td>', 'This is a superb abstract.  I just love the whole feel of it and the colours.  Can''t really tell that it is food at all.  Please let us know how you created this after voting is over.', '2006-07-21 11:59:00.000000', NULL, 1),
