(2645927, 364499, 44611, '<td valign="top">Definitely the most abstract and creative treatment of pasta in this challenge.</td>', 'Definitely the most abstract and creative treatment of pasta in this challenge.', '2006-07-21 12:01:17.000000', NULL, 1),
(2645929, 364895, 44611, '<td valign="top">Clever - and colourful.</td>', 'Clever - and colourful.', '2006-07-21 12:02:12.000000', NULL, 1),
(2645931, 364858, 44611, '<td valign="top">Looks like a sketch - clever combination of two things with natural layers.</td>', 'Looks like a sketch - clever combination of two things with natural layers.', '2006-07-21 12:03:17.000000', NULL, 1),
(2645932, 364733, 44611, '<td valign="top">Terrific mushroom macro.</td>', 'Terrific mushroom macro.', '2006-07-21 12:03:44.000000', NULL, 1),
(2645937, 364896, 44611, '<td valign="top">I like the minimalism of this, but think I would like it more without the depth of field effect.  Not totally sure but think so.</td>', 'I like the minimalism of this, but think I would like it more without the depth of field effect.  Not totally sure but think so.', '2006-07-21 12:06:11.000000', NULL, 1),
(2645939, 364773, 44611, '<td valign="top">Bumping this up on my second run through - my initial reaction was that I didn''t like the effect of the contrast play on the colours, but it''s grown on me and seems to really work for this shot.</td>', 'Bumping this up on my second run through - my initial reaction was that I didn''t like the effect of the contrast play on the colours, but it''s grown on me and seems to really work for this shot.', '2006-07-21 12:07:49.000000', NULL, 1),
(2645941, 362916, 44611, '<td valign="top">Bumping up on my second run through - while not truly abstract, the detail and effect are extremely good.</td>', 'Bumping up on my second run through - while not truly abstract, the detail and effect are extremely good.', '2006-07-21 12:08:51.000000', NULL, 1),
(2645949, 364828, 44611, '<td valign="top">Great idea but I think you either needed to focus closer to the ''dent'' in the nectarine, or choose another one with a more pronounced cleavage!</td>', 'Great idea but I think you either needed to focus closer to the ''dent'' in the nectarine, or choose another one with a more pronounced cleavage!', '2006-07-21 12:10:23.000000', NULL, 1),
(2645952, 364776, 44611, '<td valign="top">Distinctly abstract, but also rather flat and uninteresting.  This needs more contrast to increase its appeal I think.</td>', 'Distinctly abstract, but also rather flat and uninteresting.  This needs more contrast to increase its appeal I think.', '2006-07-21 12:11:51.000000', NULL, 1),
(2645965, 364686, 44611, '<td valign="top">Good idea, but hasn''t quite worked in execution. The central composition is, frankly, very boring and I can''t really see the point of having used a lime and a kiwi.  The idea of the coloured straws for the background was a brilliant one, and it works well, although I might have been inclined to line up the bendy bits as they are a bit distracting being all over the place.  This would be worth a reshoot playing with different compositions.</td>', 'Good idea, but hasn''t quite worked in execution. The central composition is, frankly, very boring and I can''t really see the point of having used a lime and a kiwi.  The idea of the coloured straws for the background was a brilliant one, and it works well, although I might have been inclined to line up the bendy bits as they are a bit distracting being all over the place.  This would be worth a reshoot playing with different compositions.', '2006-07-21 12:15:23.000000', NULL, 1),
(2645968, 364817, 44611, '<td valign="top">Its a very good kiwi shot - but I think you will suffer because it is ''just'' another kiwi shot without anything extra to garner additional appeal.</td>', 'Its a very good kiwi shot - but I think you will suffer because it is ''just'' another kiwi shot without anything extra to garner additional appeal.', '2006-07-21 12:16:28.000000', NULL, 1),
(2645975, 364741, 44611, '<td valign="top">I''m sorry but as a food shot this looks really unappetising and unexciting.</td>', 'I''m sorry but as a food shot this looks really unappetising and unexciting.', '2006-07-21 12:18:13.000000', NULL, 1),
(2645981, 362196, 44611, '<td valign="top">Terrific cookery book shot of spaghetti - but doesn''t really fit the abstract bill unfortunately.</td>', 'Terrific cookery book shot of spaghetti - but doesn''t really fit the abstract bill unfortunately.', '2006-07-21 12:19:32.000000', NULL, 1),
(2645982, 364695, 44611, '<td valign="top">Great lighting.</td>', 'Great lighting.', '2006-07-21 12:19:43.000000', NULL, 1),
(2645998, 362610, 30049, '<td valign="top">Wouldn''t have known what this is without the title - which is fine given the challenge is ''Abstract''.  The tone and detail in this image is right on the money.  DOF is very good and I love the curve of the stem coming into the image.  Given a forum thread I read earlier I''d hazard a guess as to who''s image this is.  I didn''t know Bears ate garlic!  If I''ve guessed wrong - please pardon my extra verbiage.  ;^)</td>', 'Wouldn''t have known what this is without the title - which is fine given the challenge is ''Abstract''.  The tone and detail in this image is right on the money.  DOF is very good and I love the curve of the stem coming into the image.  Given a forum thread I read earlier I''d hazard a guess as to who''s image this is.  I didn''t know Bears ate garlic!  If I''ve guessed wrong - please pardon my extra verbiage.  ;^)', '2006-07-21 12:34:11.000000', NULL, 1),
(2646002, 364763, 30049, '<td valign="top">Very DPC''ish.  ;^)  Clean, simple, well-focused, brightly colored.  Great stock image.  Yep - should do well with this one (if the Abstract DNMC folks don''t getcha).  Good luck in the challenge.</td>', 'Very DPC''ish.  ;^)  Clean, simple, well-focused, brightly colored.  Great stock image.  Yep - should do well with this one (if the Abstract DNMC folks don''t getcha).  Good luck in the challenge.', '2006-07-21 12:35:46.000000', NULL, 1),
(2646003, 364668, 30049, '<td valign="top">Very clever!  I love it.  You probably could have cropped it even just a tad tighter, but it''s fine as is.  The glass block edge makes a great natural frame for this.  Best of luck to you in the challenge.</td>', 'Very clever!  I love it.  You probably could have cropped it even just a tad tighter, but it''s fine as is.  The glass block edge makes a great natural frame for this.  Best of luck to you in the challenge.', '2006-07-21 12:38:01.000000', NULL, 1),
(2646004, 364848, 30049, '<td valign="top">Don''t have any idea what a ''Kandinsky'' is, but your image is fun to look at.  Lighting seems a bit off, like the image is underexposed.</td>', 'Don''t have any idea what a ''Kandinsky'' is, but your image is fun to look at.  Lighting seems a bit off, like the image is underexposed.', '2006-07-21 12:39:05.000000', NULL, 1),
(2646023, 364896, 30049, '<td valign="top">Going for a high-key approach?  Good concept overall.  I''m not sure how this is going to go over with voters given that highly saturated colors are the current fashion, and this is rather toned-down and flat.  I find the selection of the onion area and the distinct line with the white background a little distracting.  I think the onions should have been selected a little tighter, or maybe feather the selection more, or even use levels/curves more to bring the white up instead.  JMO of course.  Good luck.</td>', 'Going for a high-key approach?  Good concept overall.  I''m not sure how this is going to go over with voters given that highly saturated colors are the current fashion, and this is rather toned-down and flat.  I find the selection of the onion area and the distinct line with the white background a little distracting.  I think the onions should have been selected a little tighter, or maybe feather the selection more, or even use levels/curves more to bring the white up instead.  JMO of course.  Good luck.', '2006-07-21 12:45:00.000000', NULL, 1),
(2646028, 364861, 56744, '<td valign="top">Very good colors. I feel that the orange peper is too small for the amount of blue (IMO). Have luck. 7</td>', 'Very good colors. I feel that the orange peper is too small for the amount of blue (IMO). Have luck. 7', '2006-07-21 12:47:56.000000', NULL, 1),
(2646169, 364398, 24454, '<td valign="top">I love this one!  The depth of field makes it so interesting.  Good luck!</td>', 'I love this one!  The depth of field makes it so interesting.  Good luck!', '2006-07-21 13:41:13.000000', NULL, 1),
(2646174, 364487, 24454, '<td valign="top">Ooooh. . .how pretty!!!   I love the way you did the motion thing.  One of my favorites so far.</td>', 'Ooooh. . .how pretty!!!   I love the way you did the motion thing.  One of my favorites so far.', '2006-07-21 13:42:25.000000', NULL, 1),
(2646178, 364618, 24454, '<td valign="top">This one is awesome!  I could really imagine this hanging on a very contemporary kitchen wall.  Great job.</td>', 'This one is awesome!  I could really imagine this hanging on a very contemporary kitchen wall.  Great job.', '2006-07-21 13:43:47.000000', NULL, 1),
(2646186, 364906, 38496, '<td valign="top">love the ''movement'' of the lines, and the glow of the red.  Very nice.</td>', 'love the ''movement'' of the lines, and the glow of the red.  Very nice.', '2006-07-21 13:47:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2646189, 364695, 38496, '<td valign="top">This looks very cool.  Love the way the egg shells glow.</td>', 'This looks very cool.  Love the way the egg shells glow.', '2006-07-21 13:48:24.000000', NULL, 1),
(2646229, 364503, 25378, '<td valign="top">I love this! The composition is great, how the stem leads you into the cherry (?) itself. The focus on the stem tip is excellent. The blown out part on the top of the cherry really bothers me, but otherwise, great job!</td>', 'I love this! The composition is great, how the stem leads you into the cherry (?) itself. The focus on the stem tip is excellent. The blown out part on the top of the cherry really bothers me, but otherwise, great job!', '2006-07-21 14:03:30.000000', NULL, 1),
(2646423, 363457, 57202, '<td valign="top">LOL!  LMAO!  I love the idea of this photo.  I think it would have scored even higher with me if there was a little light coming in from the right-hand side though.</td>', 'LOL!  LMAO!  I love the idea of this photo.  I think it would have scored even higher with me if there was a little light coming in from the right-hand side though.', '2006-07-21 15:19:26.000000', NULL, 1),
(2646452, 364895, 57202, '<td valign="top">AWESOME photo!  A very creative idea and very well executed.  Rich colors, good lighting, and cheered me up at work.  Great job!</td>', 'AWESOME photo!  A very creative idea and very well executed.  Rich colors, good lighting, and cheered me up at work.  Great job!', '2006-07-21 15:29:06.000000', NULL, 1),
(2646511, 364848, 50695, '<td valign="top">this is magnificent. you somehow managed the light or processed it to get painterly tones. 10</td>', 'this is magnificent. you somehow managed the light or processed it to get painterly tones. 10', '2006-07-21 15:46:00.000000', NULL, 1),
