(2646566, 364604, 24454, '<td valign="top">This is so cute!  I love this composition.</td>', 'This is so cute!  I love this composition.', '2006-07-21 16:05:19.000000', NULL, 1),
(2646570, 364833, 24454, '<td valign="top">This is beautiful!  Such amazing sharpnes and interest in those rossing lines.  I love your colors too.   Definitely should be in the top 3 in my opinion!  Good luck.  10</td>', 'This is beautiful!  Such amazing sharpnes and interest in those rossing lines.  I love your colors too.   Definitely should be in the top 3 in my opinion!  Good luck.  10', '2006-07-21 16:07:39.000000', NULL, 1),
