(2647024, 364833, 29490, '<td valign="top">Guessing Karen.<br/> <br/>Great lines, great angles, cool crop, nice splash of red.</td>', 'Guessing Karen. Great lines, great angles, cool crop, nice splash of red.', '2006-07-21 18:42:32.000000', NULL, 1),
(2647111, 363994, 60224, '<td valign="top">Green pepper?</td>', 'Green pepper?', '2006-07-21 19:17:32.000000', NULL, 1),
(2647141, 362908, 60224, '<td valign="top">Where''s the beef??</td>', 'Where''s the beef??', '2006-07-21 19:36:18.000000', NULL, 1),
(2647157, 364668, 53147, '<td valign="top">I do believe this is my top choice in the challenge. Great idea, wonderful shapes and colors, just top notch all the way around. I hope you are hitting your update button cause this will be a big bump. Enjoy and good luck!</td>', 'I do believe this is my top choice in the challenge. Great idea, wonderful shapes and colors, just top notch all the way around. I hope you are hitting your update button cause this will be a big bump. Enjoy and good luck!', '2006-07-21 19:51:00.000000', NULL, 1),
(2647161, 362610, 53147, '<td valign="top">Excellent shot. A macro that works as an abstract. Nice and simple with great curves and mellow color. Great job. Bumping up.</td>', 'Excellent shot. A macro that works as an abstract. Nice and simple with great curves and mellow color. Great job. Bumping up.', '2006-07-21 19:51:56.000000', NULL, 1),
(2647165, 364907, 53147, '<td valign="top">Back to comment - I like this shot (and wish I had thought of cabbage myself).  I think I would have liked to have seen better color though. A littl ebrighter overall, whiter whites and a more saturated purple to make it just stand out strong. Great idea though - I hope it does well for you.</td>', 'Back to comment - I like this shot (and wish I had thought of cabbage myself).  I think I would have liked to have seen better color though. A littl ebrighter overall, whiter whites and a more saturated purple to make it just stand out strong. Great idea though - I hope it does well for you.', '2006-07-21 19:54:02.000000', NULL, 1),
(2647173, 363248, 53147, '<td valign="top">Nice and simple. Great gradients between the peppers and the crop works well. Nice work and bumping up.</td>', 'Nice and simple. Great gradients between the peppers and the crop works well. Nice work and bumping up.', '2006-07-21 19:55:06.000000', NULL, 1),
(2647180, 364906, 53147, '<td valign="top">One of my favorites form this challenge. I really like the color, but its the lines and textures that really set this apart. Great job - bumping up a couple.</td>', 'One of my favorites form this challenge. I really like the color, but its the lines and textures that really set this apart. Great job - bumping up a couple.', '2006-07-21 19:56:30.000000', NULL, 1),
(2647182, 364499, 53147, '<td valign="top">Great idea and well composed. Simple colors and curves give a cool artistic photo. I expect this to do well. Bumping up.</td>', 'Great idea and well composed. Simple colors and curves give a cool artistic photo. I expect this to do well. Bumping up.', '2006-07-21 19:57:25.000000', NULL, 1),
(2647191, 364760, 53147, '<td valign="top">Mmmmhhh - artichokes. We ate a coupel just last week. Great color work on this one. Glad you didnt pick a clean unmarked one as the spots and lines work great. You may be getting dinged for this being more of just a macro shot but not from me. Bumpin gup.</td>', 'Mmmmhhh - artichokes. We ate a coupel just last week. Great color work on this one. Glad you didnt pick a clean unmarked one as the spots and lines work great. You may be getting dinged for this being more of just a macro shot but not from me. Bumpin gup.', '2006-07-21 19:59:04.000000', NULL, 1),
(2647194, 362401, 53147, '<td valign="top">The best of the pasta shots. Great lighting and nice flow to the pasta. Good job. Bumping up.</td>', 'The best of the pasta shots. Great lighting and nice flow to the pasta. Good job. Bumping up.', '2006-07-21 19:59:55.000000', NULL, 1),
(2647257, 364861, 61863, '<td valign="top">I like this image, somewhat mournful - not sure why</td>', 'I like this image, somewhat mournful - not sure why', '2006-07-21 20:30:49.000000', NULL, 1),
(2647261, 363146, 61863, '<td valign="top">This image definitely works for me, good work</td>', 'This image definitely works for me, good work', '2006-07-21 20:31:06.000000', NULL, 1),
(2647262, 362610, 61863, '<td valign="top">Like the image</td>', 'Like the image', '2006-07-21 20:31:15.000000', NULL, 1),
(2647263, 364858, 61863, '<td valign="top">I really like the colours, or lack thereof - Good work</td>', 'I really like the colours, or lack thereof - Good work', '2006-07-21 20:31:25.000000', NULL, 1),
(2647270, 364560, 37893, '<td valign="top">Sensual in it''s form. I would have probably opted for a bit redder tone for the watermelon. The textures are great as is the white solid background.</td>', 'Sensual in it''s form. I would have probably opted for a bit redder tone for the watermelon. The textures are great as is the white solid background.', '2006-07-21 20:32:32.000000', NULL, 1),
(2647291, 364064, 49135, '<td valign="top">I like this pic, just wish it was bigger.</td>', 'I like this pic, just wish it was bigger.', '2006-07-21 20:35:44.000000', NULL, 1),
(2647295, 362575, 49135, '<td valign="top">Like the colors in this photo, they complement each other and definitely punch up the neutrals. Well done.</td>', 'Like the colors in this photo, they complement each other and definitely punch up the neutrals. Well done.', '2006-07-21 20:36:53.000000', NULL, 1),
(2647300, 364424, 49135, '<td valign="top">I like the blue cast on this photo, it''s makes for a very unique and interesting photo.  I think it stands apart from the other food photos.  Just wish it was sharper.</td>', 'I like the blue cast on this photo, it''s makes for a very unique and interesting photo.  I think it stands apart from the other food photos.  Just wish it was sharper.', '2006-07-21 20:38:36.000000', NULL, 1),
(2647306, 364733, 49135, '<td valign="top">Love the "rays" of the mushroom.  Wish the top piece from the stem was not sticking out.  It is slightly distracting.  But otherwise I think it''s beautifully composed and very sharp for a macro shot.</td>', 'Love the "rays" of the mushroom.  Wish the top piece from the stem was not sticking out.  It is slightly distracting.  But otherwise I think it''s beautifully composed and very sharp for a macro shot.', '2006-07-21 20:41:49.000000', NULL, 1),
(2647349, 362908, 37252, '<td valign="top">DNMC for abstract food. As a scenic, focus is soft - colors need a bit more saturation - image is flat and lacks a subject of interest. Try shooting landscapes in the landscape mode when  going for just the scenery.</td>', 'DNMC for abstract food. As a scenic, focus is soft - colors need a bit more saturation - image is flat and lacks a subject of interest. Try shooting landscapes in the landscape mode when  going for just the scenery.', '2006-07-21 20:59:48.000000', NULL, 1),
(2647361, 364819, 37252, '<td valign="top">OOF, harsh shadows, and not creatively composed - sorry but I don''t care for this one that much.</td>', 'OOF, harsh shadows, and not creatively composed - sorry but I don''t care for this one that much.', '2006-07-21 21:03:36.000000', NULL, 1),
(2647382, 364654, 37252, '<td valign="top">Interesting take on the challenge - not crazy about the colors used here, but it is interesting</td>', 'Interesting take on the challenge - not crazy about the colors used here, but it is interesting', '2006-07-21 21:10:20.000000', NULL, 1),
(2647387, 364730, 30982, '<td valign="top">Hard work on this one - nice carving job!  Light is a little flat, but I like the overall effect.</td>', 'Hard work on this one - nice carving job!  Light is a little flat, but I like the overall effect.', '2006-07-21 21:12:38.000000', NULL, 1),
(2647394, 364873, 30982, '<td valign="top">Wonderful color and silky smooth texture/flow.</td>', 'Wonderful color and silky smooth texture/flow.', '2006-07-21 21:14:39.000000', NULL, 1),
(2647395, 364592, 30982, '<td valign="top">It''s not abstract enough.  Well, you asked for it!  :-)</td>', 'It''s not abstract enough.  Well, you asked for it!  :-)', '2006-07-21 21:15:17.000000', NULL, 1),
(2647398, 364895, 30982, '<td valign="top">Heh.  Cute, and I can''t believe you placed all those little itty bitty things "just so".</td>', 'Heh.  Cute, and I can''t believe you placed all those little itty bitty things "just so".', '2006-07-21 21:16:11.000000', NULL, 1),
(2647399, 364733, 30982, '<td valign="top">Mushrooms make excellent subjects - well done.</td>', 'Mushrooms make excellent subjects - well done.', '2006-07-21 21:16:33.000000', NULL, 1),
