(2651845, 364911, 9906, '<td valign="top">Dude, what were you thinking?  :-P<br/>TC<br/><br/><i>Message edited by author 2006-07-24 01:12:10.</i></td>', 'Dude, what were you thinking?  :-PTC', '2006-07-23 19:28:25.000000', '2006-07-24 02:12:10.000000', 1),
