(2654064, 364673, 54778, '<td valign="top">I''m miffed this pic didn''t go higher..It''s very well done. Though at least the trolls didn''t get you with their 1s.<br/>Again a very cool shot</td>', 'I''m miffed this pic didn''t go higher..It''s very well done. Though at least the trolls didn''t get you with their 1s.Again a very cool shot', '2006-07-24 08:15:45.000000', NULL, 0),
(2654094, 363218, 30857, '<td valign="top">I loved this picture from the beginning ... the light, colours and composition are superb. It was one of my favorites for this challenge, and in my opinion it should have finished higher. Good job!! :-)</td>', 'I loved this picture from the beginning ... the light, colours and composition are superb. It was one of my favorites for this challenge, and in my opinion it should have finished higher. Good job!! :-)', '2006-07-24 08:25:01.000000', NULL, 0),
(2654133, 364695, 9111, '<td valign="top">Wooohooooo!!!!!!!   :D</td>', 'Wooohooooo!!!!!!!   :D', '2006-07-24 08:37:12.000000', NULL, 0),
(2654155, 364858, 30049, '<td valign="top">Just wanted to say that I really enjoyed your take on this challenge.  Very unique image with wonderful tone and texture.  I had meant to comment earlier but never got back to it.  I gave this a 9 and I''m pretty stingy on those.  ;^)  Congrat''s on your top 20 finish!</td>', 'Just wanted to say that I really enjoyed your take on this challenge.  Very unique image with wonderful tone and texture.  I had meant to comment earlier but never got back to it.  I gave this a 9 and I''m pretty stingy on those.  ;^)  Congrat''s on your top 20 finish!', '2006-07-24 08:44:59.000000', NULL, 0),
(2654158, 363248, 37719, '<td valign="top">Great shot Roxanne!  I loved the off center composition.  The blend and shift of colors is excellent (how many did you have to go through to get this combination?)  The shot is clear and very well focused.  The combination of title and composition works very well.  I love it!  Well done!<br/><br/><i>Message edited by author 2006-07-25 21:27:07.</i></td>', 'Great shot Roxanne!  I loved the off center composition.  The blend and shift of colors is excellent (how many did you have to go through to get this combination?)  The shot is clear and very well focused.  The combination of title and composition works very well.  I love it!  Well done!', '2006-07-24 08:47:37.000000', '2006-07-25 22:27:07.000000', 0),
(2654167, 364727, 37719, '<td valign="top">Well at least two of us got it!</td>', 'Well at least two of us got it!', '2006-07-24 08:50:34.000000', NULL, 0),
(2654214, 362916, 41531, '<td valign="top">congrats on your RIBBON! A beautiful image indeed!<br/><br/><i>Message edited by author 2006-07-26 10:07:42.</i></td>', 'congrats on your RIBBON! A beautiful image indeed!', '2006-07-24 09:06:15.000000', '2006-07-26 11:07:42.000000', 0),
(2654284, 364497, 2170, '<td valign="top">woot!  a hoosier ribbons!  welcome to a very exclusive club.  :) :)</td>', 'woot!  a hoosier ribbons!  welcome to a very exclusive club.  :) :)', '2006-07-24 09:26:39.000000', NULL, 0),
(2654307, 364528, 32754, '<td valign="top">I guess that food was more important than the abstract art aspect of this challenge; thought this was a good abstract and would place higher..thanks for all the positive votes, though..and thank you for the7,8,9, and 10s...sometimes, I find my interpretation of art gets in the way of my entries... <br/><br/><i>Message edited by author 2006-07-24 09:09:27.</i></td>', 'I guess that food was more important than the abstract art aspect of this challenge; thought this was a good abstract and would place higher..thanks for all the positive votes, though..and thank you for the7,8,9, and 10s...sometimes, I find my interpretation of art gets in the way of my entries... ', '2006-07-24 09:37:47.000000', '2006-07-24 10:09:27.000000', 0),
(2654309, 364833, 29490, '<td valign="top">I guessed wrong but I still love the photo!!  WTG on #5!</td>', 'I guessed wrong but I still love the photo!!  WTG on #5!', '2006-07-24 09:39:05.000000', NULL, 0),
(2654315, 362916, 24454, '<td valign="top">Way to go!!!  This is awesome!   My pick for a top 3 spot. . .but 4th is great too!!   Congratulations.<br/></td>', 'Way to go!!!  This is awesome!   My pick for a top 3 spot. . .but 4th is great too!!   Congratulations.', '2006-07-24 09:44:34.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2654319, 364733, 2240, '<td valign="top">Rikki Rikki nice photo. Congrats on another ribbon, keep it up Cap.</td>', 'Rikki Rikki nice photo. Congrats on another ribbon, keep it up Cap.', '2006-07-24 09:45:01.000000', NULL, 0),
(2654321, 363218, 24454, '<td valign="top">This is so good!  So clean and perfect.  Congratulations on such a strong finish!!!<br/> <br/></td>', 'This is so good!  So clean and perfect.  Congratulations on such a strong finish!!! ', '2006-07-24 09:45:41.000000', NULL, 0),
(2654332, 364828, 13688, '<td valign="top">hmmm...perhaps it was an apricot, I wasn''t paying close enough attention in the produce aisle.</td>', 'hmmm...perhaps it was an apricot, I wasn''t paying close enough attention in the produce aisle.', '2006-07-24 09:52:23.000000', NULL, 0),
(2654333, 364355, 2240, '<td valign="top">Sherpet you did a great job on this. Congrats on one of the top place photos.</td>', 'Sherpet you did a great job on this. Congrats on one of the top place photos.', '2006-07-24 09:53:33.000000', NULL, 0),
(2654343, 364833, 24073, '<td valign="top">Well thank you all for voting, what an amazing experience.  The comments, compliments, and critique are all well appreciated.  A special TY goes out to the select few who didn''t like the border.  I spent quite a bit of time studying borders this week, and I realized quickly a couple of things I can change.  Thanks again.   -J.</td>', 'Well thank you all for voting, what an amazing experience.  The comments, compliments, and critique are all well appreciated.  A special TY goes out to the select few who didn''t like the border.  I spent quite a bit of time studying borders this week, and I realized quickly a couple of things I can change.  Thanks again.   -J.', '2006-07-24 09:59:58.000000', NULL, 0),
(2654360, 364695, 32754, '<td valign="top">this was a stunningly clear and balanced image..congratulations</td>', 'this was a stunningly clear and balanced image..congratulations', '2006-07-24 10:08:03.000000', NULL, 0),
(2654439, 363697, 50695, '<td valign="top">I think it''s because dpc hates OOF, even if it''s abstract. I gave you a 6, which may not seem that high but it''s the same score I gave the red and yellow ribbon winners. 6 is generally my score for a good, competent shot that meets the challenge.</td>', 'I think it''s because dpc hates OOF, even if it''s abstract. I gave you a 6, which may not seem that high but it''s the same score I gave the red and yellow ribbon winners. 6 is generally my score for a good, competent shot that meets the challenge.', '2006-07-24 10:36:19.000000', NULL, 0),
(2654504, 364890, 58728, '<td valign="top">I was REALLY hoping this would be at least in the top 10!!!  I am in LOVe with this photo!  GREAT work!</td>', 'I was REALLY hoping this would be at least in the top 10!!!  I am in LOVe with this photo!  GREAT work!', '2006-07-24 10:59:34.000000', NULL, 0),
(2654510, 364355, 49652, '<td valign="top">Very nice.  Can''t imagine how long it took to arrange this!  Great job.</td>', 'Very nice.  Can''t imagine how long it took to arrange this!  Great job.', '2006-07-24 11:05:12.000000', NULL, 0),
(2654518, 364695, 36382, '<td valign="top">Congrats on your ribbon.  The yellow tones are really striking against the black.  The symmetry is very pleasing and it is nice and sharp, but not too sharp, not to my eye anyway.</td>', 'Congrats on your ribbon.  The yellow tones are really striking against the black.  The symmetry is very pleasing and it is nice and sharp, but not too sharp, not to my eye anyway.', '2006-07-24 11:10:24.000000', NULL, 0),
(2654523, 363720, 52336, '<td valign="top">Should have placed higher.  As metatate says, very classic, and beautifully done.  The vignetting makes it, adding drama to what <i>could be</i> (but definitely is not in this example) a prosaic picture.  Lovely.<br/><br/><i>Message edited by author 2006-07-24 10:15:42.</i></td>', 'Should have placed higher.  As metatate says, very classic, and beautifully done.  The vignetting makes it, adding drama to what could be (but definitely is not in this example) a prosaic picture.  Lovely.', '2006-07-24 11:13:41.000000', '2006-07-24 11:15:42.000000', 0),
(2654528, 364861, 37961, '<td valign="top">I just love your nutritional facts section. I love the red bell pepper raw. Way more than an apple or cucumber. Great healthy snacking food. You are really showing some versatility in your photography lately. Keep up the good work. The colors here really draw you in.</td>', 'I just love your nutritional facts section. I love the red bell pepper raw. Way more than an apple or cucumber. Great healthy snacking food. You are really showing some versatility in your photography lately. Keep up the good work. The colors here really draw you in.', '2006-07-24 11:15:59.000000', NULL, 0),
(2654529, 364833, 19672, '<td valign="top">Very nicely composed and layed out. What was the background?</td>', 'Very nicely composed and layed out. What was the background?', '2006-07-24 11:16:05.000000', NULL, 0),
(2654541, 363218, 52336, '<td valign="top">Nice, simple, clean execution, making a great abstract.</td>', 'Nice, simple, clean execution, making a great abstract.', '2006-07-24 11:20:34.000000', NULL, 0),
(2654556, 364708, 52336, '<td valign="top">In general, it didn''t come off as abstract as some of the other submissions.  I gave this a 5.  The setup was cute, and I like the different play of shadows on the apple (thanks for the explanation), but in my opinion the crop and the depth of field hurt this image for me.  Something more macro may have been called for to meet the challenge, but also to add interest between the contrasting colours, shapes, and textures.  I really love the coloured outtakes.  I think you should have submitted one of them, because they add a great dimension that is somehow not in your submission, for me.  Next time, go for that "stretched brain" shot. :)</td>', 'In general, it didn''t come off as abstract as some of the other submissions.  I gave this a 5.  The setup was cute, and I like the different play of shadows on the apple (thanks for the explanation), but in my opinion the crop and the depth of field hurt this image for me.  Something more macro may have been called for to meet the challenge, but also to add interest between the contrasting colours, shapes, and textures.  I really love the coloured outtakes.  I think you should have submitted one of them, because they add a great dimension that is somehow not in your submission, for me.  Next time, go for that "stretched brain" shot. :)', '2006-07-24 11:27:25.000000', NULL, 0),
(2654585, 364409, 52336, '<td valign="top">I scored this 5.  Part of that score was the selective desaturation, which is a bit "on the nose" for me in this particular picture.  Other than that, I like the setup, and the tension created by the arcing orange lifting into the other segments.  A nice abstract example.</td>', 'I scored this 5.  Part of that score was the selective desaturation, which is a bit "on the nose" for me in this particular picture.  Other than that, I like the setup, and the tension created by the arcing orange lifting into the other segments.  A nice abstract example.', '2006-07-24 11:40:53.000000', NULL, 0),
(2654611, 364430, 3724, '<td valign="top">isolation of the closeup creates some amount of abstraction,  yes the sharpen could be upped to create more clarity but maybe less abstraction. I must have been weary, for me this studio backlight has only a little of your divinity - v: 5.  Excellent composition &amp; crop.</td>', 'isolation of the closeup creates some amount of abstraction,  yes the sharpen could be upped to create more clarity but maybe less abstraction. I must have been weary, for me this studio backlight has only a little of your divinity - v: 5.  Excellent composition & crop.', '2006-07-24 11:57:24.000000', NULL, 0),
(2654628, 364274, 5585, '<td valign="top">Great shot Laura...WTG... as I can see we will finish better on average than last week... so we keep going  :)<br/> <br/>Tom</td>', 'Great shot Laura...WTG... as I can see we will finish better on average than last week... so we keep going  :) Tom', '2006-07-24 12:01:03.000000', NULL, 0),
(2654740, 364531, 33068, '<td valign="top">Not sure I understand the placement of this image.  It was my highest rated image of the bunch.  I could see this on my wall.  Excellent!</td>', 'Not sure I understand the placement of this image.  It was my highest rated image of the bunch.  I could see this on my wall.  Excellent!', '2006-07-24 12:30:41.000000', NULL, 0),
(2654753, 363218, 57839, '<td valign="top">Very nice.  I think "clean" is a very good description.  Love the color contrasts.</td>', 'Very nice.  I think "clean" is a very good description.  Love the color contrasts.', '2006-07-24 12:33:56.000000', NULL, 0),
(2654754, 364695, 57358, '<td valign="top">wow, congrats on another blue, wtg!  sweet idea btw</td>', 'wow, congrats on another blue, wtg!  sweet idea btw', '2006-07-24 12:34:10.000000', NULL, 0),
(2654759, 364497, 57358, '<td valign="top">beautiful shot, the essence of the challenge, congrats on your first ribbon!</td>', 'beautiful shot, the essence of the challenge, congrats on your first ribbon!', '2006-07-24 12:35:49.000000', NULL, 0),
(2654760, 364355, 57839, '<td valign="top">Very well presented.</td>', 'Very well presented.', '2006-07-24 12:36:17.000000', NULL, 0),
